{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 주차장 이용정보 온라인 실시간 제공 사업의 조례 근거 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시는 주차장 이용정보를 온라인으로 실시간 제공하는 스마트 주차정보를 제공할 수 있다. 이는 서울특별시 주차장 설치 및 관리 조례 제4조의3 제1항에 근거한다.",
          "b_ids": "주차장:제4조의3제1항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "주차장 이용정보 연결을 위해 자치구 또는 교통안전공단과 협력할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 스마트 주차정보를 연계·제공하기 위하여 자치구, 한국교통안전공단 등 관련 기관과 협력할 수 있다. 따라서 자치구 또는 교통안전공단과 협력하는 것이 가능하다.",
          "b_ids": "주차장:제4조의3제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
